#pragma once
// otf::OtfData -- spec tables the OTF writer needs (src/export/OtfData.cpp is
// GENERATED by scripts/otf_tables.py; the data is fixed by the specs).
namespace granjon::otf {

// CFF standard strings, SID 0..390 (CFF 1.0, Appendix A). A glyph name found
// here takes its standard SID; any other goes in the String INDEX (SID 391+).
constexpr int kCffStandardCount = 391;
extern const char* const kCffStandardStrings[kCffStandardCount];

// OS/2 ulUnicodeRange blocks: first, last, bit (OpenType OS/2 v1.7). Some bits
// own several blocks; bit 57 ("Non-Plane 0") is set for any supplementary
// code point on top of these.
struct UnicodeRangeBlock { unsigned first, last; int bit; };
extern const UnicodeRangeBlock kUnicodeRanges[];
extern const int kUnicodeRangeCount;

}  // namespace granjon::otf
